#!/usr/bin/env python3
"""One-shot evidence/Section-02 rebuild for VIGIL-INC-000002..000020.

Preserves each canonical record and mutates only adjudicated evidence, assessment,
classification-version and review-provenance fields. Intended to be removed after use.
"""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
INC = ROOT / "records" / "incidents"
TODAY = "2026-09-22"
TAX = "0.6.6"


def path(n: int) -> Path:
    return INC / f"VIGIL-INC-{n:06d}.json"


def load(n: int):
    p = path(n)
    return p, json.loads(p.read_text(encoding="utf-8"))


def save(p: Path, d: dict):
    p.write_text(json.dumps(d, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def source_exists(d: dict, url: str) -> bool:
    return any(s.get("source_url") == url for s in d.get("source_records", []))


def append_source(d: dict, s: dict):
    if source_exists(d, s["source_url"]):
        return
    s = dict(s)
    s["incident_source_order"] = len(d.get("source_records", [])) + 1
    d.setdefault("source_records", []).append(s)


def relationship(cid: str, rationale: str, canonical: bool = True, rel: str = "failure-occurrence contribution"):
    return {"class_id": cid, "relationship": rel, "canonical_taxonomy_mapping": canonical, "rationale": rationale}


def clause(paraphrase: str, invariant: str, rels: list[dict]):
    return {"source_paraphrase": paraphrase, "recovered_invariant_interpretation": invariant, "taxonomy_relationships": rels}


def review(d: dict, n: int, outcome: str):
    r = {
        "review_id": f"VIGIL-REVIEW-2026-09-22-EVIDENCE-REBUILD-{n:06d}",
        "reviewer_type": "AI analytical reviewer",
        "reviewer_platform": "OpenAI ChatGPT",
        "reviewer_model": "GPT-5.6 Sol",
        "review_date": TODAY,
        "review_scope": "Evidence-spine health review, source-clause governance reassessment and current-taxonomy reconciliation. Existing occurrence and Harm Impact findings were preserved unless stronger occurrence evidence materially required clarification.",
        "capability_profile": {
            "direct_repository_analysis": True,
            "direct_text_analysis": True,
            "web_link_and_metadata_review": True,
            "structured_semantic_adjudication": True,
            "full_current_taxonomy_review": True,
            "new_external_source_research": True,
        },
        "known_limitations": [
            "The review distinguishes occurrence evidence from contextual research and does not promote context-only sources into occurrence proof.",
            "Absence of a current taxonomy mapping is not treated as absence of a real incident or governance concern.",
        ],
        "review_outcome": outcome,
    }
    ip = d.setdefault("interpretive_provenance", {})
    hist = ip.setdefault("review_history", [])
    if not any(x.get("review_id") == r["review_id"] for x in hist):
        hist.append(r)
    ip["current_ai_review"] = r


def touch(d: dict):
    ri = d.setdefault("record_identity", {})
    ri["updated"] = TODAY
    # Rebuild tranche is a material analytical revision.
    if ri.get("version", "").startswith("1."):
        ri["version"] = "1.2.0"


def set_tax_version(d: dict):
    tc = d.get("taxonomy_classification")
    if isinstance(tc, dict):
        tc["taxonomy_version"] = TAX
        prov = tc.setdefault("classification_review_provenance", {})
        prov["review_date"] = TODAY
        prov["method"] = "evidence-spine rebuild and deterministic current-taxonomy reconciliation against VIGIL Failure Taxonomy 0.6.6"


def assess(d: dict, factual: str, governance: str, significance: str, boundaries: list[str], source_order: int | None, source_url: str | None, purpose: str | None, clauses: list[dict] | None):
    a = d.setdefault("vigil_assessment", {})
    a["factual_basis"] = factual
    a["governance_interpretation"] = governance
    a["significance_to_cam"] = significance
    a["assessment_boundaries"] = boundaries
    if source_order is not None and source_url and clauses is not None:
        a["source_clause_analysis"] = {
            "source_record_order": source_order,
            "source_url": source_url,
            "purpose": purpose or "Resolve occurrence evidence into governance principles before formal taxonomy mapping.",
            "clauses": clauses,
        }


