# Shared facial-recognition helper.
def face_review(n:int, factual:str, governance:str, significance:str, boundaries:list[str], source_order:int, source_url:str, clauses_:list[dict], outcome:str):
    p,d=load(n); touch(d); set_tax_version(d)
    tc=d["taxonomy_classification"]
    tc["classification_status"]="classified"
    pc=tc.get("primary_classification") or {}
    pc.update({"family_id":"VIGIL-FF-0001","class_id":"VIGIL-FC-000046","classification_role":"failure-occurrence"})
    tc["primary_classification"]=pc
    tc["classification_basis"]="Current-taxonomy review retains VIGIL-FC-000046 Inferential Evidence–Authority Conflation. The class applies to the evidenced promotion of a probabilistic facial-recognition lead through a liberty-affecting investigative pathway without sufficient independent assurance for the coercive use made of the resulting identity inference; it does not assert that facial recognition alone was the sole cause of every downstream police or judicial decision."
    assess(d,factual,governance,significance,boundaries,source_order,source_url,"Resolve the occurrence-specific facial-recognition evidence into the distinction between inferential identity evidence and coercive decision authority.",clauses_)
    review(d,n,outcome); save(p,d)

